import ajax from '@/utils/ajax';
import { action, observable, makeObservable } from 'mobx';

class Store {
    @observable tagId: string = "";
    @action
    setTagId = (id) => {
        this.tagId = id;
    }



    @observable list: any[] = [];
    @action setList = (data) => {
        this.list = data;
    }


    getList = () => {
        const params: any = { };
        if(this.tagId){
            params.tagId = this.tagId;
        }
        
        ajax.post('/apijson/get', {
            "ImageList[]": {
                "count": 100,
                "ImageList": {
                    ...params,
                    "@column": "id,name,url",
                }
            }
        }).then((res) => {
            this.setList(res.ImageList);
        })
    }


    @observable tags: any[] = [];
    @action setTags = (data) => {
        this.tags = data;
    }


    getTags = () => {
        ajax.post('/apijson/get', {
            "ImageTag[]": {
                "ImageTag": {
                    "isActive": 1,
                    "@column": "id, name"
                }
            }
        }).then((res) => {
            this.setTags(res.ImageTag);
        })
    }

    constructor() {
        makeObservable(this);
    }
}


export default new Store();